from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
import inspect
from databricks.sdk.service import database as db
print('database methods:', [a for a in dir(w.database) if not a.startswith('_')])
print('--- existing online stores ---')
try:
    for s in w.feature_store.list_online_stores():
        print(s.name, s.capacity, s.state)
except Exception as e:
    print('list err:', str(e)[:200])
print('--- existing db instances ---')
try:
    for i in w.database.list_database_instances():
        print(i.name, getattr(i,'capacity',None), getattr(i,'state',None))
except Exception as e:
    print('db list err:', str(e)[:200])
